const TagFrame = styled(Text, {
	...tagFrame,
	variants: {
		paint: tagPaints,
		shape: tagShapes,
		fontScale: tagScales,
	},
});

const TagInner = styled(Text, tagInner);

const stateOf = (clickable: boolean, disabled: boolean) => {
	if (disabled) return clickable ? 'clickable-disabled' : 'muted';
	return clickable ? 'clickable' : 'rest';
};

const scaleOf = (large?: boolean, medium?: boolean) => {
	if (large) return 'large';
	return medium ? 'medium' : undefined;
};

/**
 * Used for mentions
 */
const Tag = (props: TagProps) => {
	const { large, medium, pill, className, disabled, variant, children, icon, href, onPress, onClick } = props;
	const clickable = Boolean(onPress || onClick || href);

	const modifiers = [variant, medium && 'medium', large && 'large', pill && 'pill', disabled && 'disabled', clickable && 'clickable']
		.filter(Boolean)
		.map((modifier) => `rcx-tag--${modifier}`)
		.join(' ');

	const paint = `${variant ?? 'default'}|${stateOf(clickable, Boolean(disabled))}` as const;
	const fontScale = scaleOf(large, medium);

	const classes = prependClassName(className, `rcx-box rcx-box--full rcx-tag ${modifiers}`);

	const content = (
		// The tag is not a Box, so without this the margins of a Margins above it would land on the Boxes inside it
		<BoxTransforms.Provider value={null}>
			{icon}
			<TagInner className='rcx-tag__inner'>{children}</TagInner>
		</BoxTransforms.Provider>
	);

	if (href) {
		return (
			<PressTarget press={props}>
				<TagFrame
					paint={paint}
					shape={pill ? 'pill' : 'regular'}
					fontScale={fontScale}
					className={classes}
					render={
						<a
							{...ariaAndDataAttributes(props)}
							{...pickWebPressHandlers(props)}
							href={href}
							target={props.target}
							rel={props.rel}
							ref={props.ref as WebLinkRef}
							id={props.id}
							title={props.title}
							role={props.role}
							tabIndex={props.tabIndex}
						/>
					}
				>
					{content}
				</TagFrame>
			</PressTarget>
		);
	}

	return (
		<PressTarget press={props}>
			<TagFrame
				paint={paint}
				shape={pill ? 'pill' : 'regular'}
				fontScale={fontScale}
				className={classes}
				render={
					<span
						{...ariaAndDataAttributes(props)}
						{...pickWebPressHandlers(props)}
						ref={props.ref}
						id={props.id}
						title={props.title}
						role={props.role}
						tabIndex={props.tabIndex}
					/>
				}
			>
				{content}
			</TagFrame>
		</PressTarget>
	);
};

export default Tag;
